import urllib.request
import re

url = "https://arxiv.org/abs/0909.0950v4"
try:
    response = urllib.request.urlopen(url, timeout=10)
    html = response.read().decode('utf-8')
    print("Abstract page fetched successfully")

    # Search for key terms
    if "overlap" in html.lower():
        print("Found 'overlap' in page")
    if "c = " in html.lower() or "c=" in html.lower():
        print("Found 'c =' in page")
    if "|x_i" in html or "|x_i>" in html:
        print("Found basis notation")

    # Extract the abstract
    # Find the abstract section
    start = html.find('<blockquote class="abstract mathjax">')
    if start == -1:
        start = html.find('<span class="abstract-full">')
    if start == -1:
        start = html.find('abstract')

    if start != -1:
        end = html.find('</blockquote>', start)
        if end == -1:
            end = html.find('</span>', start)
        if end != -1:
            abstract = html[start:end]
            # Clean up
            import re
            abstract = re.sub('<[^>]+>', '', abstract)
            print(f"\nAbstract excerpt:\n{abstract[:2000]}")
except Exception as e:
    print(f"Error: {e}")
